(()=>{"use strict";
const U=document.currentScript?.src||"",R=U?new URL("../../",U).href:"",L=R?new URL("Lovelo_Black.otf",R).href:"",Q=R?new URL("Quicksand-VariableFont_wght.ttf",R).href:"",W=window.self!==window.top;
const DEMO={itemCount:2,subtotal:"HK$996.00",items:[{id:"canvas",name:"Canvas",quantity:1,unitPrice:"HK$498.00",lineTotal:"HK$498.00",previewText:"Happy birthday, Mia!",options:[{name:"Flavour",value:"Chocolate"},{name:"Topping",value:"No Thanks"},{name:"Decor",value:"Letters"}]},{id:"cake",name:"Birthday Suit",quantity:1,unitPrice:"HK$498.00",lineTotal:"HK$498.00",options:[{name:"Flavour",value:"Classic"}]}]};
function fonts(){if(!L||document.head.querySelector("[data-qcp-fonts]"))return;const s=document.createElement("style");s.dataset.qcpFonts="1";s.textContent=`@font-face{font-family:Lovelo;src:url('${L}') format('opentype');font-weight:900;font-display:swap}@font-face{font-family:Quicksand;src:url('${Q}') format('truetype');font-weight:300 700;font-display:swap}`;document.head.appendChild(s)}
const money=v=>Number(String(v||"").replace(/[^0-9.-]+/g,""))||0,fmt=v=>`HK$${Number(v||0).toLocaleString("en-HK",{minimumFractionDigits:2,maximumFractionDigits:2})}`;
class QuesoCartPage extends HTMLElement{
static get observedAttributes(){return["cart-data","cart-busy","cart-message"]}constructor(){super();this.attachShadow({mode:"open"})}connectedCallback(){fonts();this.toggleAttribute("data-wix-frame",W);this.render();this.bind()}attributeChangedCallback(n,o,v){if(!this.isConnected||o===v)return;if(n==="cart-data"){this.render();this.bind()}else this.feedback()}
val(n,f=""){const v=this.getAttribute(n);return v===null||!v.trim()?f:v.trim()}json(n,f){try{const v=this.val(n);return v?JSON.parse(v):f}catch(e){console.error("Queso cart page JSON error",e);return f}}esc(v){return String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}get cart(){const c=this.json("cart-data",null);return c&&typeof c==="object"?c:DEMO}get busy(){return["true","1","yes","on"].includes(this.val("cart-busy","false").toLowerCase())}
thumb(i){const p=String(i.previewImage||""),t=String(i.previewText||""),x=String(i.image||"");if(p)return`<div class="thumb"><img src="${this.esc(p)}" alt="${this.esc(i.name)} customization"></div>`;if(t)return`<div class="thumb text"><span>${this.esc(t)}</span></div>`;if(x)return`<div class="thumb"><img src="${this.esc(x)}" alt="${this.esc(i.name)}"></div>`;return`<div class="thumb blank">Q</div>`}
opts(i){const a=Array.isArray(i.options)?i.options:[];return a.length?`<dl>${a.map(o=>`<div><dt>${this.esc(o.name)}</dt><dd>${this.esc(o.value)}</dd></div>`).join("")}</dl>`:""}
item(i){const id=String(i.id||""),q=Math.max(1,Number(i.quantity||1));return`<article data-line-item="${this.esc(id)}">${this.thumb(i)}<div class="copy"><header><div><h2>${this.esc(i.name||"Queso cake")}</h2><p class="unit">${this.esc(i.unitPrice||"")}</p></div><button class="remove" data-remove="${this.esc(id)}" ${this.busy?"disabled":""}>Remove</button></header>${this.opts(i)}<footer><div class="qty"><button data-qty="${this.esc(id)}" data-next="${Math.max(1,q-1)}" ${this.busy||q<=1?"disabled":""}>−</button><span>${q}</span><button data-qty="${this.esc(id)}" data-next="${q+1}" ${this.busy?"disabled":""}>+</button></div><strong class="line">${this.esc(i.lineTotal||i.unitPrice||"")}</strong></footer></div></article>`}
render(){const c=this.cart,a=Array.isArray(c.items)?c.items:[],n=Math.max(0,Number(c.itemCount||0)),m=this.val("cart-message","");this.shadowRoot.innerHTML=`<style>
:host{--o:#ed6011;--c:#fdf3e6;--y:#f4c24a;--b:#3d2416;--p:#efa3b5;display:block;width:100%;height:100%;min-height:0;overflow:hidden;background:var(--c);color:var(--b);font:550 14px Quicksand,Arial,sans-serif}:host([data-wix-frame]){height:auto}:host([data-wix-frame]) .page{position:fixed;inset:0;overflow:auto}*{box-sizing:border-box}button{font:inherit;color:inherit;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}.page{min-height:100%;padding:clamp(34px,5vw,76px) clamp(18px,5vw,80px);background:var(--c)}.top{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:44px}.eye{margin:0 0 9px;color:#a84c09;font-size:11px;font-weight:850;letter-spacing:.15em;text-transform:uppercase}h1,h2,.sum h2{font-family:Lovelo,Arial,sans-serif;text-transform:uppercase}h1{margin:0;font-size:clamp(60px,7vw,108px);line-height:.88}.meta{display:grid;gap:11px;justify-items:end}.count{margin:0;font-weight:800}.continue{min-height:44px;padding:0 18px;border:2px solid var(--b);background:transparent;font-size:11px;font-weight:850;text-transform:uppercase}.layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.72fr);gap:clamp(28px,5vw,72px);align-items:start}.items{border-top:2px solid var(--b)}article{display:grid;grid-template-columns:150px minmax(0,1fr);gap:23px;padding:27px 0;border-bottom:1px solid #3d24164d}.thumb{position:relative;width:150px;aspect-ratio:1;display:grid;place-items:center;overflow:hidden;border:2px solid var(--b);background:#fff}.thumb img{width:100%;height:100%;object-fit:cover}.thumb.text{padding:18px;text-align:center;background:var(--c)}.thumb.text:before{content:"";position:absolute;inset:11px;border:1px dashed #3d24166b}.thumb.text span{position:relative;z-index:1;max-width:88%;font:900 16px/1.03 Lovelo,Arial,sans-serif;text-transform:uppercase;overflow-wrap:anywhere}.thumb.blank{background:var(--o);color:#fff;font:900 60px Lovelo,Arial}.copy{min-width:0}.copy header{display:flex;justify-content:space-between;align-items:start;gap:15px}.copy h2{margin:0;font-size:clamp(22px,2.2vw,31px);line-height:1}.unit{margin:7px 0 0;color:#df6a06;font-weight:800}.remove{padding:3px 0;border:0;border-bottom:1px solid;background:transparent;font-size:10px;font-weight:850;text-transform:uppercase}dl{display:grid;gap:6px;margin:17px 0 0;font-size:12px}dl div{display:grid;grid-template-columns:minmax(72px,auto) minmax(0,1fr);gap:9px}dt{font-weight:850}dd{margin:0;overflow-wrap:anywhere}.copy footer{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:21px}.qty{display:grid;grid-template-columns:38px 44px 38px;min-height:40px;border:1px solid var(--b)}.qty button{border:0;background:#fff;font-size:19px}.qty span{display:grid;place-items:center;border-inline:1px solid #3d241640;font-weight:850}.line{font:900 19px Lovelo,Arial}.sum{position:sticky;top:22px;padding:27px;border:2px solid var(--b);background:var(--y)}.sum h2{margin:0 0 23px;font-size:30px}.row{display:flex;align-items:baseline;justify-content:space-between;gap:18px;padding:14px 0;border-top:1px solid #3d241652}.row strong{font:900 22px Lovelo,Arial;text-align:right}.note{margin:4px 0 18px;font-size:10px;line-height:1.5}.status{min-height:18px;margin:0 0 9px;color:#a52a23;font-size:11px;font-weight:800}.checkout{width:100%;min-height:54px;padding:12px;border:2px solid var(--b);background:var(--o);color:#fff;font-size:11px;font-weight:900;text-transform:uppercase}.empty{min-height:430px;display:grid;place-items:center;align-content:center;gap:13px;padding:45px 20px;border-bottom:2px solid var(--b);text-align:center}.empty strong{font:900 32px Lovelo,Arial;text-transform:uppercase}.empty p{max-width:400px;margin:0;line-height:1.6}@media(max-width:900px){.layout{grid-template-columns:1fr}.sum{position:static}}@media(max-width:620px){.page{padding:34px 18px 44px}.top{align-items:start;flex-direction:column;gap:17px;margin-bottom:30px}h1{font-size:clamp(58px,20vw,78px)}.meta{width:100%;justify-items:stretch}.continue{width:100%}article{grid-template-columns:90px minmax(0,1fr);gap:12px;padding:21px 0}.thumb{width:90px}.thumb.text{padding:9px}.thumb.text:before{inset:7px}.thumb.text span{font-size:11px}.copy h2{font-size:18px}.remove{font-size:9px}dl{margin-top:11px;gap:4px;font-size:10px}dl div{grid-template-columns:47px minmax(0,1fr);gap:6px}.copy footer{align-items:start;flex-direction:column;gap:9px;margin-top:13px}.qty{grid-template-columns:32px 36px 32px;min-height:35px}.line{font-size:14px}.sum{padding:22px 19px}}
</style><main class="page"><header class="top"><div><p class="eye">Almost yours</p><h1>Your cart.</h1></div><div class="meta"><p class="count">${n} ${n===1?"item":"items"}</p><button class="continue" data-continue>Continue shopping</button></div></header><div class="layout"><section class="items">${a.length?a.map(i=>this.item(i)).join(""):`<div class="empty"><strong>Your cart is empty.</strong><p>Choose a Queso cake, make it yours, then return here when you are ready.</p><button class="continue" data-continue>Shop the cakes</button></div>`}</section><aside class="sum"><h2>Order summary</h2><div class="row"><span>Estimated subtotal</span><strong data-subtotal>${this.esc(c.subtotal||"HK$0.00")}</strong></div><div class="row"><span>Delivery</span><strong>—</strong></div><p class="note">Delivery, taxes and discounts are confirmed during checkout.</p><p class="status" aria-live="polite">${this.esc(m)}</p><button class="checkout" data-checkout ${this.busy||!a.length?"disabled":""}>Secure checkout</button></aside></div></main>`}
feedback(){const s=this.shadowRoot?.querySelector(".status");if(s)s.textContent=this.val("cart-message","");const b=this.shadowRoot?.querySelector("[data-checkout]");if(b)b.disabled=this.busy||!this.shadowRoot.querySelector("[data-line-item]")}
emit(n,d={}){this.dispatchEvent(new CustomEvent(n,{bubbles:true,composed:true,detail:d}))}
quantity(b){const a=b.closest("[data-line-item]"),c=b.closest(".qty"),s=c?.querySelector("span");if(!a||!c||!s)return;const old=Math.max(1,Number(s.textContent||1)),q=Math.max(1,Number(b.dataset.next||old));if(q===old)return;const unit=money(a.querySelector(".unit")?.textContent),d=q-old;s.textContent=q;const bs=c.querySelectorAll("[data-qty]");if(bs[0]){bs[0].dataset.next=Math.max(1,q-1);bs[0].disabled=q<=1}if(bs[1])bs[1].dataset.next=q+1;const line=a.querySelector(".line");if(line&&unit)line.textContent=fmt(unit*q);const count=this.shadowRoot.querySelector(".count");if(count){const x=Math.max(0,parseInt(count.textContent)||0)+d;count.textContent=`${x} ${x===1?"item":"items"}`}const sub=this.shadowRoot.querySelector("[data-subtotal]");if(sub&&unit)sub.textContent=fmt(Math.max(0,money(sub.textContent)+unit*d))}
remove(b){const a=b.closest("[data-line-item]");if(!a)return;const q=Math.max(1,Number(a.querySelector(".qty span")?.textContent||1)),amt=money(a.querySelector(".line")?.textContent)||money(a.querySelector(".unit")?.textContent)*q;a.remove();const left=this.shadowRoot.querySelectorAll("[data-line-item]");const count=this.shadowRoot.querySelector(".count");if(count){const x=Math.max(0,(parseInt(count.textContent)||0)-q);count.textContent=`${x} ${x===1?"item":"items"}`}const sub=this.shadowRoot.querySelector("[data-subtotal]");if(sub)sub.textContent=fmt(Math.max(0,money(sub.textContent)-amt));if(!left.length){this.shadowRoot.querySelector(".items").innerHTML=`<div class="empty"><strong>Your cart is empty.</strong><p>Choose a Queso cake, make it yours, then return here when you are ready.</p><button class="continue" data-continue>Shop the cakes</button></div>`;this.shadowRoot.querySelector("[data-continue]")?.addEventListener("click",()=>this.emit("queso-cart-page-continue"));const x=this.shadowRoot.querySelector("[data-checkout]");if(x)x.disabled=true}}
bind(){this.shadowRoot.querySelectorAll("[data-continue]").forEach(b=>b.addEventListener("click",()=>this.emit("queso-cart-page-continue")));this.shadowRoot.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{const id=String(b.dataset.remove||"");this.remove(b);this.emit("queso-cart-page-remove",{lineItemId:id})}));this.shadowRoot.querySelectorAll("[data-qty]").forEach(b=>b.addEventListener("click",()=>{const id=String(b.dataset.qty||""),quantity=Math.max(1,Number(b.dataset.next||1));this.quantity(b);this.emit("queso-cart-page-quantity-change",{lineItemId:id,quantity})}));this.shadowRoot.querySelector("[data-checkout]")?.addEventListener("click",()=>this.emit("queso-cart-page-checkout"))}}
if(!customElements.get("queso-cart-page"))customElements.define("queso-cart-page",QuesoCartPage);
})();